CREATE TABLE IF NOT EXISTS documentos_venta(dov_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,dov_tip VARCHAR(3) NOT NULL,dov_num VARCHAR(30) NOT NULL,clc_id BIGINT NOT NULL,dov_fec DATE NOT NULL,dov_est VARCHAR(20) NOT NULL,dov_id_ori BIGINT,dov_id_rai BIGINT,dov_imp_sub NUMERIC(14,2),dov_imp_des NUMERIC(14,2),dov_imp_iva NUMERIC(14,2),dov_imp_tot NUMERIC(14,2),dov_obs VARCHAR(500),dov_usu_mov VARCHAR(100) NOT NULL,dov_fec_mov TIMESTAMP NOT NULL,dov_act BOOLEAN NOT NULL,CONSTRAINT uk_documento_venta_numero UNIQUE(cli_id,dov_tip,dov_num));
CREATE TABLE IF NOT EXISTS documentos_venta_detalle(dvd_id BIGSERIAL PRIMARY KEY,dov_id BIGINT NOT NULL,dvd_tip_lin VARCHAR(1) NOT NULL,pro_id BIGINT,ser_id BIGINT,dvd_nom VARCHAR(200) NOT NULL,dvd_can INTEGER NOT NULL,dvd_pre NUMERIC(14,2) NOT NULL,dvd_des NUMERIC(7,2) NOT NULL,dvd_iva NUMERIC(7,2) NOT NULL,dvd_imp NUMERIC(14,2) NOT NULL,dvd_dur_uni INTEGER NOT NULL,dvd_dur_tot INTEGER NOT NULL,CONSTRAINT fk_dvd_documento FOREIGN KEY(dov_id) REFERENCES documentos_venta(dov_id),CONSTRAINT ck_dvd_tipo CHECK((dvd_tip_lin='P' AND pro_id IS NOT NULL AND ser_id IS NULL)OR(dvd_tip_lin='S' AND ser_id IS NOT NULL AND pro_id IS NULL)));
